        END IF;

        v_affected := false;
        IF v_capacity_ratio < 0.85 THEN
            v_affected := true;
        END IF;
        IF v_actual_efficiency < para_eer_threshold::numeric THEN
            v_affected := true;
        END IF;
        IF v_carnot_cop IS NOT NULL AND v_actual_cop < 0.04 * v_carnot_cop THEN
            v_affected := true;
        END IF;
        IF v_setpoint_flag THEN
            v_affected := true;
        END IF;

        IF NOT v_affected THEN
            CONTINUE;
        END IF;

        IF v_capacity_ratio > 0 THEN
            v_multiplier := 1.0 / v_capacity_ratio;
        ELSE
            v_multiplier := 1.0;
        END IF;

        UPDATE energy_consumption
           SET energy_consumption_kwh = energy_consumption_kwh * v_multiplier
         WHERE ac_id = v_ac_id
           AND mode = para_target_mode;

        IF v_capacity_ratio < 0.85 THEN
            UPDATE air_conditioner_info
               SET power_consumption_watts = power_consumption_watts * LEAST(1.5, 1.0 + (1.0 - v_capacity_ratio))
             WHERE ac_id = v_ac_id;
        END IF;

        IF v_sample_days > 0 THEN
            v_annual_emissions := (v_total_consumption / v_sample_days::numeric) * 365.0 * 0.000233;
        ELSE
            v_annual_emissions := (v_original_power / 1000.0) * 1000.0 * 0.000233;
        END IF;

        INSERT INTO carbon_emissions (id, emission_factor, annual_emissions_tonnes)
        VALUES (v_next_id, 0.000233, v_annual_emissions);

        v_next_id := v_next_id + 1;
    END LOOP;
END;
$$;
